// Turn the AI answer into the same record shape as a reference match - without trusting it blindly:
// the invoice must exist in the list the model was given, otherwise the payment goes to review.
const src = $('Merge Invoices with Unmatched Payments').item.json;
const ai = $input.item.json.output || {};
const candidates = Array.isArray(src.open_invoices) ? src.open_invoices : [];
const key = (v) => String(v ?? '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
const wanted = key(ai.invoice_id);
const invoice = wanted ? candidates.find(c => c && (key(c.inv_id) === wanted || key(c.inv_number) === wanted)) : undefined;

const payment = {};
for (const k of Object.keys(src)) if (k.startsWith('tx_')) payment[k] = src[k];

let confidence = Math.round(Number(ai.confidence));
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(100, confidence));
if (!invoice) confidence = 0; // the model named an invoice that is not in the list, or nothing at all

const outstanding = invoice ? Number(invoice.inv_outstanding) || 0 : 0;
const amount = Number(payment.tx_amount) || 0;

return { json: {
  ...payment,
  ...(invoice || {}),
  matched: Boolean(invoice),
  match_method: 'AI (GPT-4o-mini)',
  confidence,
  ai_invoice_id: String(ai.invoice_id || '').trim(),
  ai_match_type: String(ai.match_type || (invoice ? 'unknown' : 'none')),
  reasoning: String(ai.reasoning || '').trim() || (invoice ? 'No reasoning returned by the model' : 'No matching invoice found'),
  amount_diff: invoice ? Math.round((amount - outstanding) * 100) / 100 : null,
} };

