// Weekly accounts-receivable aging report: overdue open invoices bucketed by days late, one HTML email
const BUCKETS = [[1, 30], [31, 60], [61, 90], [91, Infinity]];
const MAX_ROWS = 50; // longest table you want in the email

const now = new Date();
const todayUtc = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
const toDate = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return new Date(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000); // Google Sheets serial date
  const s = String(v).trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) return new Date(Date.UTC(+iso[1], +iso[2] - 1, +iso[3]));
  const eu = s.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})$/); // dd.mm.yyyy or dd/mm/yyyy
  if (eu) return new Date(Date.UTC(+eu[3], +eu[2] - 1, +eu[1]));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
};
const toNumber = (v) => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[^\d.,-]/g, '');
  if (/^-?\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(s)) s = s.replace(/\./g, ''); // 1.250,00 -> 1250,00
  const n = Number(s.replace(/,(\d{1,2})$/, '.$1').replace(/,/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const money = (n) => (Math.round(n * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const isoDate = (d) => d.toISOString().slice(0, 10);

const overdue = [];
for (const { json: r } of $input.all()) {
  if (!r || r.InvoiceNumber === undefined || String(r.InvoiceNumber).trim() === '') continue;
  const due = toDate(r.DueDate ?? r['Due date']);
  if (!due) continue;
  const days = Math.round((todayUtc - due.getTime()) / 86400000);
  const outstanding = Math.round((toNumber(r.Amount) - toNumber(r.PaidAmount)) * 100) / 100;
  if (days < 1 || outstanding <= 0) continue;
  overdue.push({
    number: String(r.InvoiceNumber).trim(), client: String(r.ClientName ?? r.Customer ?? '').trim(), email: String(r.ClientEmail ?? r.Email ?? '').trim(),
    currency: String(r.Currency ?? '').trim().toUpperCase(), status: String(r.Status ?? 'Open').trim() || 'Open', due: isoDate(due), days, outstanding,
  });
}
overdue.sort((a, b) => b.days - a.days || b.outstanding - a.outstanding);

const totals = {}; // per currency
const buckets = BUCKETS.map(([from, to]) => ({ label: to === Infinity ? from + '+ days' : from + '-' + to + ' days', count: 0, sums: {} }));
for (const inv of overdue) {
  totals[inv.currency] = (totals[inv.currency] || 0) + inv.outstanding;
  const b = buckets.find(x => inv.days >= BUCKETS[buckets.indexOf(x)][0] && inv.days <= BUCKETS[buckets.indexOf(x)][1]);
  if (b) { b.count++; b.sums[inv.currency] = (b.sums[inv.currency] || 0) + inv.outstanding; }
}
const fmtSums = (sums) => Object.keys(sums).sort().map(c => money(sums[c]) + ' ' + c).join(', ') || '-';
const asOf = isoDate(new Date(todayUtc));

if (!overdue.length) {
  return [{ json: {
    subject: 'Aging report ' + asOf + ': no overdue invoices',
    html: '<p>Good news: as of ' + asOf + ' there are no overdue open invoices in the sheet.</p>',
    overdue_count: 0, totals: {},
  } }];
}

const rows = overdue.slice(0, MAX_ROWS).map(inv => '<tr><td>' + esc(inv.number) + '</td><td>' + esc(inv.client) + '</td><td>' + esc(inv.due) + '</td>' +
  '<td style="text-align:right">' + inv.days + '</td><td style="text-align:right">' + money(inv.outstanding) + ' ' + esc(inv.currency) + '</td><td>' + esc(inv.status) + '</td></tr>').join('');
const bucketRows = buckets.map(b => '<tr><td>' + b.label + '</td><td style="text-align:right">' + b.count + '</td><td>' + esc(fmtSums(b.sums)) + '</td></tr>').join('');
const html = '<h2>Overdue invoices as of ' + asOf + '</h2>' +
  '<p><b>' + overdue.length + '</b> overdue invoice(s), total outstanding <b>' + esc(fmtSums(totals)) + '</b></p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Days overdue</th><th>Invoices</th><th>Outstanding</th></tr>' + bucketRows + '</table>' +
  '<h3>Details' + (overdue.length > MAX_ROWS ? ' (top ' + MAX_ROWS + ' of ' + overdue.length + ')' : '') + '</h3>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Invoice</th><th>Client</th><th>Due</th><th>Days</th><th>Outstanding</th><th>Status</th></tr>' + rows + '</table>' +
  '<p style="color:#666">Generated by the n8n payment reconciliation workflow. Invoices marked Paid or Overpaid are excluded.</p>';

return [{ json: {
  subject: 'Aging report ' + asOf + ': ' + overdue.length + ' overdue, ' + fmtSums(totals) + ' outstanding',
  html, overdue_count: overdue.length, totals,
} }];
